// Mutual consumption (orders <-> payments), generated by the `veld` binary.
// Both servers run, each calls the other through its generated client, and errors raised in one
// service arrive in the other as the right class with the right operation signature.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import http from 'node:http';
import type { AddressInfo } from 'node:net';
import * as ordersSrv from './servers/orders/index';
import * as paymentsSrv from './servers/payments/index';
import * as web from './web/index';
import { OrdersClient } from './web/orders/client';
import { PaymentsClient } from './web/payments/client';

const sigs = JSON.parse(readFileSync('sigs.json', 'utf8')) as Record<string, string>;
const sig = (name: string): string => {
  const s = sigs[name];
  assert.ok(s, `no signature for ${name}`);
  return s;
};

const PAID = '11111111-1111-4111-8111-111111111111';
const UNPAID = '22222222-2222-4222-8222-222222222222';
const GHOST = '33333333-3333-4333-8333-333333333333';

const knownOrders = new Set([PAID, UNPAID]);
const amounts = new Map([[PAID, 4200]]);

let ordersUrl = '';
let paymentsUrl = '';
let paymentsCalledByOrders = 0;
let ordersCalledByPayments = 0;
const caught: unknown[] = [];

const ordersImpl: ordersSrv.OrdersService = {
  async getOrder(req) {
    if (!knownOrders.has(req.id)) throw new ordersSrv.NotFound({ resource: 'order' });
    // orders -> payments, through the client generated inside the orders server.
    const payments = new ordersSrv.payments.PaymentsClient({ baseUrl: paymentsUrl });
    paymentsCalledByOrders += 1;
    try {
      const p = await payments.getPaymentByOrder({ orderId: req.id });
      return { id: req.id, payment: `paid:${String(p.amount)}` };
    } catch (e) {
      if (ordersSrv.payments.NotFound.matches(e)) {
        caught.push(e);
        return { id: req.id, payment: 'none' };
      }
      throw e;
    }
  },
  async getSummary(req) {
    ordersCalledByPayments += 1;
    if (!knownOrders.has(req.id)) throw new ordersSrv.NotFound({ resource: 'order' });
    return { id: req.id };
  },
};

const paymentsImpl: paymentsSrv.PaymentsService = {
  async getPaymentByOrder(req) {
    // payments -> orders, through the client generated inside the payments server.
    const orders = new paymentsSrv.orders.OrdersClient({ baseUrl: ordersUrl });
    try {
      await orders.getSummary({ id: req.orderId });
    } catch (e) {
      if (paymentsSrv.orders.NotFound.matches(e)) throw new paymentsSrv.NotFound({ resource: 'order' });
      throw e;
    }
    const amount = amounts.get(req.orderId);
    if (amount === undefined) throw new paymentsSrv.NotFound({ resource: 'payment' });
    return { id: req.orderId, orderId: req.orderId, amount };
  },
};

function listen(server: http.Server): Promise<string> {
  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => resolve(`http://127.0.0.1:${String((server.address() as AddressInfo).port)}`));
  });
}

async function main(): Promise<void> {
  // Each server consumes the other, so its runtime config needs the other's URL, which exists once
  // both are listening: they start with a listener that is replaced when the handlers are built.
  let ordersListener: http.RequestListener = (_req, res) => res.writeHead(503).end();
  let paymentsListener: http.RequestListener = (_req, res) => res.writeHead(503).end();
  const ordersServer = http.createServer((req, res) => ordersListener(req, res));
  const paymentsServer = http.createServer((req, res) => paymentsListener(req, res));
  ordersUrl = await listen(ordersServer);
  paymentsUrl = await listen(paymentsServer);
  ordersListener = ordersSrv.toNodeHttp(
    ordersSrv.createOrdersHandler(ordersImpl, {}, { services: { payments: { url: paymentsUrl } } }),
  );
  paymentsListener = paymentsSrv.toNodeHttp(
    paymentsSrv.createPaymentsHandler(paymentsImpl, {}, { services: { orders: { url: ordersUrl } } }),
  );
  try {
    await scenario();
  } finally {
    ordersServer.close();
    paymentsServer.close();
    ordersServer.closeAllConnections();
    paymentsServer.closeAllConnections();
  }
}

async function scenario(): Promise<void> {
  // The TypeScript client target talks to both servers.
  const orders = new OrdersClient({ baseUrl: ordersUrl });
  const payments = new PaymentsClient({ baseUrl: paymentsUrl });

  // 1. A full cycle: web -> orders -> payments -> orders (summary).
  const paid = await orders.getOrder({ id: PAID });
  assert.deepEqual(paid, { id: PAID, payment: 'paid:4200' });
  assert.equal(paymentsCalledByOrders, 1, 'orders called payments');
  assert.equal(ordersCalledByPayments, 1, 'payments called orders back');

  // 2. A NotFound raised in payments arrives in orders' client as payments' NotFound class,
  //    carrying payments' operation signature.
  const unpaid = await orders.getOrder({ id: UNPAID });
  assert.deepEqual(unpaid, { id: UNPAID, payment: 'none' });
  assert.equal(caught.length, 1, 'orders caught the error from payments');
  const err = caught[0] as InstanceType<typeof ordersSrv.payments.NotFound>;
  assert.ok(err instanceof ordersSrv.payments.NotFound, 'the payments client class');
  assert.ok(!(err instanceof ordersSrv.NotFound), 'not orders own NotFound class');
  assert.equal(err.status, 404);
  assert.equal(err.op, sig('Payments.getPaymentByOrder'), 'payments op signature');
  assert.deepEqual(err.data, { resource: 'payment' });
  // Equality is by signature, operation and data, never by class.
  const fromPayments = new web.NotFound({ resource: 'payment' }, { op: sig('Payments.getPaymentByOrder') });
  const fromOrders = new web.NotFound({ resource: 'payment' }, { op: sig('Orders.getOrder') });
  assert.ok(web.same(err, fromPayments), 'same across generated copies');
  assert.ok(!web.same(err, fromOrders), 'a NotFound from another service is different');

  // 3. A NotFound raised by orders itself.
  await assert.rejects(orders.getOrder({ id: GHOST }), (e: unknown) => {
    assert.ok(e instanceof web.NotFound);
    assert.equal(e.op, sig('Orders.getOrder'));
    assert.deepEqual(e.data, { resource: 'order' });
    assert.ok(web.NotFound.matches(e, 'orders/Orders'));
    assert.ok(!web.NotFound.matches(e, 'orders/Payments'));
    return true;
  });

  // 4. payments asks orders, orders says NotFound, payments turns that into its own NotFound.
  await assert.rejects(payments.getPaymentByOrder({ orderId: GHOST }), (e: unknown) => {
    assert.ok(e instanceof web.NotFound);
    assert.equal(e.op, sig('Payments.getPaymentByOrder'));
    assert.deepEqual(e.data, { resource: 'order' });
    return true;
  });

  // 5. A nonsense id never reaches the other service: validation fails first.
  const before = ordersCalledByPayments;
  await assert.rejects(payments.getPaymentByOrder({ orderId: 'not-a-uuid' }), (e: unknown) => e instanceof web.ValidationError);
  assert.equal(ordersCalledByPayments, before);
}

main().then(
  () => process.stdout.write('mutual ok\n'),
  (e: unknown) => {
    console.error(e);
    process.exit(1);
  },
);
